import type { AvatarSize } from './Avatar.types';

export const AVATAR_DEFAULT_SIZE: AvatarSize = 'large';

export const AVATAR_DEFAULT_VARIANT_TYPE = 'initials' as const;

export const AVATAR_SIZE_DIMENSIONS: Record<
  AvatarSize,
  { width: string; height: string; fontSize: string }
> = {
  large: { width: '24px', height: '24px', fontSize: '0.75rem' },
  xlarge: { width: '32px', height: '32px', fontSize: '1rem' },
  xxlarge: { width: '64px', height: '64px', fontSize: '1.5rem' },
  xxxlarge: { width: '96px', height: '96px', fontSize: '2rem' },
};

export const AVATAR_BACKGROUND_TOKEN_MAP: Record<string, string> = {
  primary: 'brandPrimaryBasis',
  'accent-neutral': 'brandPrimaryBasis',
  'accent-cold': 'brandPrimaryBasis',
  'accent-warm': 'brandPrimaryBasis',
  'accent-exciting': 'brandPrimaryBasis',
};
